INSERT INTO etl.dq_check (check_name, layer, severity, check_sql) VALUES
 (N'fact_sales_line: grain is unique', N'dw', N'ERROR', N'SELECT COUNT(*) FROM (SELECT sales_order_id, sales_order_detail_id FROM dw.fact_sales_line GROUP BY sales_order_id, sales_order_detail_id HAVING COUNT(*) > 1) AS x'),
 (N'fact_sales_quota: grain is unique', N'dw', N'ERROR', N'SELECT COUNT(*) FROM (SELECT quota_month_key, salesperson_key FROM dw.fact_sales_quota GROUP BY quota_month_key, salesperson_key HAVING COUNT(*) > 1) AS x'),
 (N'fact_purchase_line: grain is unique', N'dw', N'ERROR', N'SELECT COUNT(*) FROM (SELECT purchase_order_id, purchase_order_detail_id FROM dw.fact_purchase_line GROUP BY purchase_order_id, purchase_order_detail_id HAVING COUNT(*) > 1) AS x'),
 (N'fact_inventory: grain is unique', N'dw', N'ERROR', N'SELECT COUNT(*) FROM (SELECT product_key, location_key FROM dw.fact_inventory GROUP BY product_key, location_key HAVING COUNT(*) > 1) AS x'),
 (N'fact_headcount_monthly: grain is unique', N'dw', N'ERROR', N'SELECT COUNT(*) FROM (SELECT month_end_date_key, employee_key FROM dw.fact_headcount_monthly GROUP BY month_end_date_key, employee_key HAVING COUNT(*) > 1) AS x'),
