 (N'fact_sales_line.order_date_key: no orphan keys to dim_date', N'dw', N'ERROR', N'SELECT COUNT(*) FROM dw.fact_sales_line AS f LEFT JOIN dw.dim_date AS d ON f.order_date_key = d.date_key WHERE f.order_date_key IS NOT NULL AND d.date_key IS NULL'),
