 (N'fact_payroll_monthly.month_end_date_key: no orphan keys to dim_date', N'dw', N'ERROR', N'SELECT COUNT(*) FROM dw.fact_payroll_monthly AS f LEFT JOIN dw.dim_date AS d ON f.month_end_date_key = d.date_key WHERE f.month_end_date_key IS NOT NULL AND d.date_key IS NULL'),
 (N'fact_payroll_monthly.department_key: no orphan keys to dim_department', N'dw', N'ERROR', N'SELECT COUNT(*) FROM dw.fact_payroll_monthly AS f LEFT JOIN dw.dim_department AS d ON f.department_key = d.department_key WHERE f.department_key IS NOT NULL AND d.department_key IS NULL'),
 (N'fact_payroll_monthly.territory_key: no orphan keys to dim_territory', N'dw', N'ERROR', N'SELECT COUNT(*) FROM dw.fact_payroll_monthly AS f LEFT JOIN dw.dim_territory AS d ON f.territory_key = d.territory_key WHERE f.territory_key IS NOT NULL AND d.territory_key IS NULL'),
 (N'dim_employee.territory_key: no orphan keys to dim_territory', N'dw', N'ERROR', N'SELECT COUNT(*) FROM dw.dim_employee AS f LEFT JOIN dw.dim_territory AS d ON f.territory_key = d.territory_key WHERE f.territory_key IS NOT NULL AND d.territory_key IS NULL'),
 (N'dim_vendor.territory_key: no orphan keys to dim_territory', N'dw', N'ERROR', N'SELECT COUNT(*) FROM dw.dim_vendor AS f LEFT JOIN dw.dim_territory AS d ON f.territory_key = d.territory_key WHERE f.territory_key IS NOT NULL AND d.territory_key IS NULL'),
 (N'reconcile: sales lines = staging SalesOrderDetail rows', N'dw', N'ERROR', N'SELECT CASE WHEN (SELECT COUNT(*) FROM dw.fact_sales_line) = (SELECT COUNT(*) FROM stg.SalesOrderDetail) THEN 0 ELSE 1 END'),
 (N'reconcile: net sales = staging SUM(LineTotal)', N'dw', N'ERROR', N'SELECT CASE WHEN ABS((SELECT SUM(net_sales_amount) FROM dw.fact_sales_line) - (SELECT SUM(LineTotal) FROM stg.SalesOrderDetail)) <= 0.05 THEN 0 ELSE 1 END'),
 (N'reconcile: allocated freight = staging SUM(header Freight) (+-1.00)', N'dw', N'ERROR', N'SELECT CASE WHEN ABS((SELECT SUM(allocated_freight_amount) FROM dw.fact_sales_line) - (SELECT SUM(Freight) FROM stg.SalesOrderHeader)) <= 1.00 THEN 0 ELSE 1 END'),
 (N'reconcile: purchase lines = staging PurchaseOrderDetail rows', N'dw', N'ERROR', N'SELECT CASE WHEN (SELECT COUNT(*) FROM dw.fact_purchase_line) = (SELECT COUNT(*) FROM stg.PurchaseOrderDetail) THEN 0 ELSE 1 END'),
 (N'reconcile: purchase spend = staging SUM(LineTotal)', N'dw', N'ERROR', N'SELECT CASE WHEN ABS((SELECT SUM(line_total_amount) FROM dw.fact_purchase_line) - (SELECT SUM(LineTotal) FROM stg.PurchaseOrderDetail)) <= 0.05 THEN 0 ELSE 1 END'),
 (N'reconcile: inventory rows = staging ProductInventory rows', N'dw', N'ERROR', N'SELECT CASE WHEN (SELECT COUNT(*) FROM dw.fact_inventory) = (SELECT COUNT(*) FROM stg.ProductInventory) THEN 0 ELSE 1 END'),
 (N'reconcile: latest month-end headcount = current employees', N'dw', N'ERROR', N'SELECT CASE WHEN (SELECT SUM(headcount_flag) FROM dw.fact_headcount_monthly WHERE month_end_date_key = (SELECT MAX(month_end_date_key) FROM dw.fact_headcount_monthly)) = (SELECT COUNT(*) FROM stg.Employee WHERE CurrentFlag = 1) THEN 0 ELSE 1 END'),
 (N'reconcile: payroll employee-months = headcount snapshot rows', N'dw', N'ERROR', N'SELECT CASE WHEN (SELECT SUM(employee_count) FROM dw.fact_payroll_monthly) = (SELECT SUM(headcount_flag) FROM dw.fact_headcount_monthly) THEN 0 ELSE 1 END'),
 (N'sales: quantities and net sales are positive', N'dw', N'ERROR', N'SELECT COUNT(*) FROM dw.fact_sales_line WHERE order_quantity <= 0 OR net_sales_amount < 0'),
 (N'purchases: quantities are non-negative', N'dw', N'ERROR', N'SELECT COUNT(*) FROM dw.fact_purchase_line WHERE order_quantity <= 0 OR received_quantity < 0 OR rejected_quantity < 0'),
 (N'sales: unknown customer/product/territory lookups (late-arriving dimension)', N'dw', N'WARN', N'SELECT COUNT(*) FROM dw.fact_sales_line WHERE customer_key = -1 OR product_key = -1 OR territory_key = -1'),
 (N'purchases: unknown vendor/product/territory lookups', N'dw', N'WARN', N'SELECT COUNT(*) FROM dw.fact_purchase_line WHERE vendor_key = -1 OR product_key = -1 OR territory_key = -1'),
 (N'headcount: employees without a department at month end', N'dw', N'WARN', N'SELECT COUNT(*) FROM dw.fact_headcount_monthly WHERE department_key = -1'),
 (N'sales: lines costed with the product''s current standard cost (no cost-history row)', N'dw', N'WARN', N'SELECT COUNT(*) FROM stg.SalesOrderDetail AS d JOIN stg.SalesOrderHeader AS h ON h.SalesOrderID = d.SalesOrderID LEFT JOIN stg.ProductCostHistory AS c ON c.ProductID = d.ProductID AND h.OrderDate >= c.StartDate AND (c.EndDate IS NULL OR h.OrderDate <= c.EndDate) WHERE c.ProductID IS NULL'),
 (N'staging: header/detail integrity (detail lines without a header)', N'staging', N'ERROR', N'SELECT COUNT(*) FROM stg.SalesOrderDetail AS d LEFT JOIN stg.SalesOrderHeader AS h ON h.SalesOrderID = d.SalesOrderID WHERE h.SalesOrderID IS NULL'),
 (N'staging: purchase detail without a header', N'staging', N'ERROR', N'SELECT COUNT(*) FROM stg.PurchaseOrderDetail AS d LEFT JOIN stg.PurchaseOrderHeader AS h ON h.PurchaseOrderID = d.PurchaseOrderID WHERE h.PurchaseOrderID IS NULL');
            INSERT INTO @r EXEC sys.sp_executesql @sql;
        INSERT INTO etl.dq_result (batch_id, run_id, check_id, check_name, severity, violations, status)
